from PIL import Image, ImageOps, ImageDraw
im=Image.open('/app/pantomograph.jpg')
def crop(name,box):
    c=ImageOps.autocontrast(im.crop(box),cutoff=1).convert('RGB')
    d=ImageDraw.Draw(c)
    for x in range((box[0]//50+1)*50,box[2],50):
        d.line([(x-box[0],0),(x-box[0],8 if x%100 else 20)],fill=(255,0,0),width=2)
        if x%100==0: d.text((x-box[0]+2,22),str(x),fill=(255,0,0))
    for y in range((box[1]//50+1)*50,box[3],50):
        d.line([(0,y-box[1]),(8 if y%100 else 20,y-box[1])],fill=(255,0,0),width=2)
        if y%100==0: d.text((22,y-box[1]),str(y),fill=(255,0,0))
    c.save(name)
crop('r.png',(550,350,1300,950))
crop('c.png',(1150,350,1800,950))
crop('l.png',(1650,350,2350,950))
"", "description": "Make contrast-enhanced crops with coordinate ticks"}

