from PIL import Image, ImageOps, ImageDraw
im=Image.open('/app/pantomograph.jpg')
def crop(name,box,s=2):
    c=ImageOps.equalize(im.crop(box)).convert('RGB')
    c=c.resize((c.width*s//2*1,c.height*s//2*1))
    d=ImageDraw.Draw(c); k=s/2
    for x in range((box[0]//25+1)*25,box[2],25):
        d.line([((x-box[0])*k,0),((x-box[0])*k,8 if x%100 else 20)],fill=(255,0,0),width=2)
        if x%100==0: d.text(((x-box[0])*k+2,22),str(x),fill=(255,0,0))
    for y in range((box[1]//25+1)*25,box[3],25):
        d.line([(0,(y-box[1])*k),(8 if y%100 else 20,(y-box[1])*k)],fill=(255,0,0),width=2)
        if y%100==0: d.text((22,(y-box[1])*k),str(y),fill=(255,0,0))
    c.save(name)
crop('lr.png',(550,600,1300,1000),3)
crop('ll.png',(1500,600,2300,1000),3)
